I have a task for you to complete. Here are the instructions:
Con base en la información proporcionada en {{conversation.SummaryAgent.summary}}, guarda en pocas 256 caracteres el motivo de contacto del cliente en {{user.description}}  
--
The following is the typescript interface I need as output of the task:

```typescript
interface Output = {
  /** descripcion de motivo de contacto */
"description": string
}

instructions.code:
const phone = user.phone

const sensitiveData = {
  "TELÉFONO": phone ?? '',
  "NOMBRE": user.fullName ?? '',
  "UBICACIÓN_USUARIO": user.location ?? '',
  "CÉDULA": user.nationalID ?? '',
  "NÚMERO_FACTURA": user.brillaBillNumber ?? '',
  "TIPO_DE_CONTRATO": user.jobContractType ?? ''
}

const nonSensitiveData = {
  "RESUMEN": user.description ?? '',
  "ESTATUS": user.conversationStatus ?? '',
  "ASISTENCIA": user.assistanceMode ?? '',
  "ROL_DE_CLIENTE": user.clientRole ?? '',
  "PERFIL_CREDITICIO": user.creditProfile ?? '',
  "REPORTADO": user.negativeCreditReport ?? '',
  "PREFERENCIA_DE_COMPRA": user.purchasePreference ?? '',
  "PRODUCTO_DE_INTERÉS": user.interestedProduct?.reference ?? '',
  "CONCLUSIÓN": user.conversationEnding ?? '',
  "UBICACIÓN_SERVICIO": user.serviceLocation ?? ''
}
const rowData = user.popAuthorized ? { ...sensitiveData, ...nonSensitiveData } : { ...nonSensitiveData }
console.log(`🤖 Saving rowData:`, rowData);

try {
  const existingRecord = await leadClientsTable.findRecords({
    filter: { "TELÉFONO": phone }
  })

  if (existingRecord.length > 0) {
    const recordId = existingRecord[0].id
    await leadClientsTable.updateRecord(recordId, rowData)
  } else {
    await leadClientsTable.createRecord(rowData)
  }
} catch (error) {
  console.error(' ❌ Error saving data:', error)
}

